ALTER TABLE jobs ADD COLUMN subtitle_event_owned boolean NOT NULL DEFAULT false;
ALTER TABLE reader_problems ADD COLUMN subtitle_due double precision;
ALTER TABLE reader_problems ADD COLUMN subtitle_reserved_owned boolean NOT NULL DEFAULT false;
CREATE INDEX reader_subtitle_due ON reader_problems(subtitle_due,id COLLATE "C") WHERE subtitle_due IS NOT NULL AND subtitle_reserved_owned;
CREATE INDEX jobs_subtitle_event_owned ON jobs(id) WHERE kind='download_media' AND subtitle_event_owned;
CREATE INDEX reader_subtitle_reservation_job ON reader_problems ((md5(body::jsonb->>'media_job_id')),(md5(body::jsonb->>'subtitle_canonical'))) WHERE subtitle_due IS NOT NULL AND subtitle_reserved_owned AND identity LIKE 'subtitle:reservation:%';
DROP INDEX jobs_unmanaged_problems;
CREATE INDEX jobs_unmanaged_problems ON jobs(kind,item) WHERE kind IS DISTINCT FROM 'read' AND kind IS DISTINCT FROM 'discover' AND problem_code IS DISTINCT FROM 'processor-config' AND NOT (kind IN ('delete','feed-delete') AND coalesce(nullif(problem_code,''),'work-'||kind) IN ('delete','feed-delete','work-delete','work-feed-delete')) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch') AND NOT fetch_null_ambiguous) AND (problem_code IS NOT NULL OR error IS NOT NULL) AND NOT (kind IS NOT DISTINCT FROM 'download_media' AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')) AND NOT ((kind IS NOT DISTINCT FROM 'filter' OR kind IS NOT DISTINCT FROM 'theses') AND item IS NOT NULL AND item<>'' AND (((problem_code='' OR (problem_code IS NULL AND error IS NOT NULL))) OR (problem_code IS NOT NULL AND problem_code<>'' AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch')))) AND NOT (kind IN ('fetch','download_media','filter','theses','delete','feed-delete') AND problem_code IS NOT NULL AND problem_code LIKE 'source-%' AND source_event_owned) AND NOT (kind IS NOT DISTINCT FROM 'fetch' AND problem_code IS NULL AND error IS NOT NULL AND fetch_null_owned) AND problem_code IS DISTINCT FROM 'youtube-admission' AND NOT (kind IS NOT DISTINCT FROM 'download_media' AND subtitle_event_owned);
CREATE INDEX jobs_subtitle_unowned ON jobs(item) WHERE kind='download_media' AND NOT subtitle_event_owned AND item IS NOT NULL AND item<>'' AND problem_code IS NOT NULL AND problem_code NOT LIKE 'source-%' AND problem_code NOT IN ('codex-choice','ai-permission','youtube-admission','processor-config','identity-unconfirmed','profile_not_configured','profile_unavailable','account_identity_mismatch');
CREATE INDEX reader_subtitle_legacy_paged ON reader_problems ((md5(substring(coalesce(body::jsonb->>'media_job_identity',body::jsonb->>'status_job_identity',identity) FROM ':download_media:(.*)$'))),(md5(id))) WHERE finished IS NULL AND identity LIKE 'job:%' AND body::jsonb->>'code'='work-download_media' AND body::jsonb->>'operation' IN ('producer:download_media','producer:status');
CREATE INDEX reader_subtitle_media_isolated_paged ON reader_problems ((md5(body::jsonb->>'media_job_identity')),(md5(id))) WHERE finished IS NULL AND body::jsonb->>'operation'='producer:download_media' AND body::jsonb->>'media_job_identity' IS NOT NULL;
CREATE INDEX reader_subtitle_status_isolated_paged ON reader_problems ((md5(body::jsonb->>'status_job_identity')),(md5(id))) WHERE finished IS NULL AND body::jsonb->>'operation'='producer:download_media' AND body::jsonb->>'status_job_identity' IS NOT NULL;
CREATE INDEX state_subtitle_reservation ON state(key COLLATE "C") WHERE key COLLATE "C">='subtitle:reservation:' AND key COLLATE "C"<'subtitle:reservation;';
